<script setup lang="ts">
import TechnicalGoals from './TechnicalGoals.vue'
import type {DashboardTarget} from '../domain/dashboard'
import {computed,onMounted,ref} from 'vue'
import {technicalDrills,technicalTopics,technicalById,technicalStacks,technicalLevels,filterTechnical} from '../domain/technical'
import {useInterviewStore} from '../stores/interview'
const props=defineProps<{initialTarget?:DashboardTarget}>()
const emit=defineEmits<{open:[id:string]}>(),store=useInterviewStore(),topic=ref('ALL'),stack=ref('ALL'),level=ref('ALL'),query=ref(''),error=ref(''),starting=ref(false)
onMounted(()=>store.init())
const bank=computed(()=>filterTechnical(topic.value,stack.value,level.value,query.value))
const attempts=computed(()=>store.attempts.filter(a=>technicalById(a.questionId)).sort((a,b)=>b.createdAt-a.createdAt))
async function start(id:string){if(starting.value)return;starting.value=true;try{error.value='';const attempt=store.start(id);await store.flush();emit('open',attempt)}catch{error.value='Chưa lưu được bài luyện. Giữ trang mở, kiểm tra lỗi Interview hoặc mở bản nháp hiện có trước khi tạo thêm.'}finally{starting.value=false}}
</script>
<template><div data-testid="technical-drills"><div class="eyebrow">TECHNICAL DRILL · AUTHOR_CREATED</div><h1 class="page-title">Luyện giải thích kỹ thuật</h1><p class="lead">API, SQL và security qua tình huống cụ thể. Nêu giả định, lựa chọn và cách kiểm chứng.</p><div class="notice">Sáu bài tự biên soạn. Nhãn Ứng dụng/Phân tích mô tả phạm vi bài, chưa là độ khó được hiệu chuẩn hay cấp độ năng lực. Dùng luồng Interview để lưu transcript, tự review chứng cứ, hàng đợi và Guided/Independent retry. Không thực thi code/SQL, không kết luận đúng sai chỉ từ từ khóa và không suy kinh nghiệm từ CV. AI/voice vẫn theo consent riêng của Interview.</div><p v-if="error" role="alert">{{error}}</p><p v-if="store.error" role="alert">{{store.error}}</p><p v-if="!store.ready">Đang đọc dữ liệu luyện…</p><template v-else><section class="card form-card"><label>Chủ đề Technical Drill<select v-model="topic"><option value="ALL">Tất cả</option><option v-for="t in technicalTopics" :key="t" :value="t">{{t}}</option></select></label><label>Stack bài luyện<select v-model="stack"><option value="ALL">Tất cả stack</option><option v-for="s in technicalStacks" :key="s" :value="s">{{s}}</option></select></label><label>Phạm vi bài luyện<select v-model="level"><option value="ALL">Tất cả phạm vi</option><option v-for="(name,id) in technicalLevels" :key="id" :value="id">{{name}}</option></select></label><label>Tìm bài kỹ thuật<input v-model="query" maxlength="100"></label><p v-if="store.loadFailed">N/A · Chưa đọc được lịch sử kỹ thuật.</p><p v-else>{{attempts.length}} attempts kỹ thuật · {{attempts.filter(a=>a.status==='DRAFT').length}} bản nháp · {{attempts.filter(a=>a.status==='REVIEWED').length}} đã gửi. Đây là số thao tác, không phải năng lực kỹ thuật.</p></section><div class="question-grid"><article v-for="q in bank" :key="q.id" class="card question-card"><span class="pill">{{q.topic}} · {{q.stack}} · {{technicalLevels[q.level as keyof typeof technicalLevels]}}</span><h2>{{q.title}}</h2><p lang="ja">{{q.japanese}}</p><p>{{q.intent}}</p><button class="primary" :disabled="starting||store.busy||store.loadFailed" @click="start(q.id)">Luyện bài kỹ thuật</button></article></div><p v-if="!bank.length">Không có bài phù hợp.</p><section class="card form-card"><h2>Lịch sử Technical Drill</h2><p>Chung IndexedDB và backup Interview. Backup/xóa Interview bao gồm cả Technical Drill; không có bản sao dữ liệu riêng. Số phiên3 lượt cũ giữ nguyên kịch bản.</p><p v-if="store.loadFailed">N/A · Chưa đọc được lịch sử kỹ thuật.</p><p v-else-if="!attempts.length">Chưa có lượt kỹ thuật.</p><article v-for="a in attempts" :key="a.id" class="mode-box"><h3>{{technicalById(a.questionId)?.title}}</h3><p>{{a.status}} · {{a.mode}} · {{new Date(a.createdAt).toLocaleString('vi-VN')}} · transcript v{{a.revisions.length}}</p><button :disabled="starting" @click="emit('open',a.id)">{{a.status==='DRAFT'?'Tiếp tục bài kỹ thuật':'Mở review kỹ thuật'}}</button></article></section><TechnicalGoals :initial-goal-id="props.initialTarget?.kind==='TECHNICAL_GOAL'?props.initialTarget.id:undefined" :focus="props.initialTarget?.kind==='TECHNICAL_GOALS'" :attempts="store.loadFailed?null:store.attempts" @open="id=>emit('open',id)"/></template></div></template>
